/bin/bash -lc "python - <<'PY'
from pathlib import Path
source = Path('broken.js').read_text()
old = '''function parseLine(line) {
  return line.split(\",\");
}'''
new = '''function parseLine(line) {
  const cells = [];
  let cell = \"\";
  let quoted = false;
  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    if (char === '\"') {
      if (quoted && line[i + 1] === '\"') {
        cell += '\"';
        i++;
      } else {
        quoted = "'!quoted;
      }
    } else if (char === "," && !quoted) {
      cells.push(cell);
      cell = "";
    } else {
      cell += char;
    }
  }
  cells.push(cell);
  return cells;
}'"'''
if old not in source:
    raise SystemExit('Expected parseLine implementation not found')
corrected = source.replace(old, new, 1)
Path('answer.txt').write_text('"'```js'"\\n' + corrected.rstrip('\\n') + '\\n"'```'"\\n')
PY"

